compile.workshop:
variables {
    global:
        0: code
        1: n
        127: __emptyString__
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(__emptyString__, Char In String(Empty Array, Null));
    }
}

//Optimize for size enabled
rule ("operands") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.code == Custom String("");
        Global.code != Custom String("");
    }
    actions {
        While(((Compare(Global.code, ==, Global.__emptyString__)) && (Compare(Global.code, !=, Global.__emptyString__))));
            Set Global Variable(n, 1);
            Wait(True, Ignore Condition);
        End;
    }
}

